import sys
from functools import lru_cache
class Solution:
    def minMoves(self, sx, sy, tx, ty):
        if sx == 0 and sy == 0:
            return 0 if sx == tx and sy == ty else -1
        sys.setrecursionlimit(100000)
        INF = float('inf')
        @lru_cache(maxsize=None)
        def go(x, y):
            if x == sx and y == sy:
                return 0
            if x < sx or y < sy:
                return INF
            best = INF
            if x > y:
                if y > 0 and x - y <= y and x - y >= 0:
                    d = (x - sx) // y if y == sy else 1
                    nx = x - d * y
                    if nx >= sx and (nx != x):
                        best = min(best, d + go(nx, y))
                if x % 2 == 0 and x // 2 >= y:
                    best = min(best, 1 + go(x // 2, y))
            elif y > x:
                if x > 0 and y - x <= x:
                    d = (y - sy) // x if x == sx else 1
                    ny = y - d * x
                    if ny >= sy and ny != y:
                        best = min(best, d + go(x, ny))
                if y % 2 == 0 and y // 2 >= x:
                    best = min(best, 1 + go(x, y // 2))
            else:
                best = min(best, 1 + go(0, y), 1 + go(x, 0))
            return best
        ans = go(tx, ty)
        return ans if ans < INF else -1

