class Solution {
    long sx, sy;
    Map<Long, Long> memo = new HashMap<>();

    public int minMoves(int sx_, int sy_, int tx, int ty) {
        sx = sx_; sy = sy_;
        if (sx == 0 && sy == 0) return (sx == tx && sy == ty) ? 0 : -1;
        long ans = go(tx, ty);
        return ans >= Long.MAX_VALUE / 2 ? -1 : (int) ans;
    }

    private long go(long x, long y) {
        if (x == sx && y == sy) return 0;
        if (x < sx || y < sy) return Long.MAX_VALUE / 2;
        long key = x * 2000000001L + y;
        Long cached = memo.get(key);
        if (cached != null) return cached;
        long best = Long.MAX_VALUE / 2;
        if (x > y) {
            if (y > 0 && x - y <= y) {
                long d = (y == sy) ? (x - sx) / y : 1;
                long nx = x - d * y;
                if (nx >= sx && nx < x) best = Math.min(best, d + go(nx, y));
            }
            if (x % 2 == 0 && x / 2 >= y) best = Math.min(best, 1 + go(x / 2, y));
        } else if (y > x) {
            if (x > 0 && y - x <= x) {
                long d = (x == sx) ? (y - sy) / x : 1;
                long ny = y - d * x;
                if (ny >= sy && ny < y) best = Math.min(best, d + go(x, ny));
            }
            if (y % 2 == 0 && y / 2 >= x) best = Math.min(best, 1 + go(x, y / 2));
        } else {
            best = Math.min(best, 1 + Math.min(go(0, y), go(x, 0)));
        }
        memo.put(key, best);
        return best;
    }
}

