var minMoves = function(sx, sy, tx, ty) {
    if (sx === 0 && sy === 0) return (sx === tx && sy === ty) ? 0 : -1;
    const INF = Infinity;
    const memo = new Map();
    function go(x, y) {
        if (x === sx && y === sy) return 0;
        if (x < sx || y < sy) return INF;
        const key = x * 2000000001 + y;
        if (memo.has(key)) return memo.get(key);
        let best = INF;
        if (x > y) {
            if (y > 0 && x - y <= y) {
                const d = (y === sy) ? Math.floor((x - sx) / y) : 1;
                const nx = x - d * y;
                if (nx >= sx && nx < x) best = Math.min(best, d + go(nx, y));
            }
            if (x % 2 === 0 && x / 2 >= y) best = Math.min(best, 1 + go(x / 2, y));
        } else if (y > x) {
            if (x > 0 && y - x <= x) {
                const d = (x === sx) ? Math.floor((y - sy) / x) : 1;
                const ny = y - d * x;
                if (ny >= sy && ny < y) best = Math.min(best, d + go(x, ny));
            }
            if (y % 2 === 0 && y / 2 >= x) best = Math.min(best, 1 + go(x, y / 2));
        } else {
            best = Math.min(best, 1 + go(0, y), 1 + go(x, 0));
        }
        memo.set(key, best);
        return best;
    }
    const ans = go(tx, ty);
    return ans === INF ? -1 : ans;
};
